const terminalizeExpiredReadyAndClaimReplacement = `-- name: TerminalizeExpiredReadyAndClaimReplacement :one
WITH terminalized AS (
    UPDATE public.chat_mutation_approval_executions AS execution
    SET
        status = 'completed',
        output = CAST($7 AS jsonb),
        completed_at = CURRENT_TIMESTAMP,
        lease_token = NULL,
        lease_expires_at = NULL,
        failed_at = NULL,
        failure_code = NULL,
        updated_at = CURRENT_TIMESTAMP
    WHERE execution.session_id = $8
      AND execution.user_id = $5
      AND execution.workspace_id = $6
      AND execution.tool_call_id = $9
      AND execution.fingerprint = $2
      AND execution.status = 'ready'
      AND execution.lease_expires_at <= CURRENT_TIMESTAMP
    RETURNING 1
)
INSERT INTO public.chat_mutation_approval_executions AS replacement (
    session_id,
    user_id,
    workspace_id,
    tool_call_id,
    fingerprint,
    status,
    lease_token,
    lease_expires_at,
    attempt_count
)
SELECT
    destination.id,
    destination.user_id,
    destination.workspace_id,
    $1,
    $2,
    'ready',
    $3,
    CURRENT_TIMESTAMP + INTERVAL '30 seconds',
    1
FROM public.chat_sessions AS destination
CROSS JOIN terminalized
WHERE destination.id = $4
  AND destination.user_id = $5
  AND destination.workspace_id = $6
  AND destination.deleted_at IS NULL
RETURNING replacement.session_id, replacement.user_id, replacement.workspace_id, replacement.tool_call_id, replacement.fingerprint, replacement.status, replacement.output, replacement.created_at, replacement.updated_at, replacement.completed_at, replacement.lease_token, replacement.lease_expires_at, replacement.started_at, replacement.failed_at, replacement.failure_code, replacement.attempt_count, replacement.last_reconciliation_resolution, replacement.last_reconciliation_evidence, replacement.last_reconciled_at, replacement.reconciliation_count
`

